CREATE TABLE IF NOT EXISTS `notification_source_group_routes` (
    `source_deployment_id` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `tenant_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `legacy_group_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `engine` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `notification_group_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `bound_notification_group_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `group_revision` BIGINT NOT NULL DEFAULT 0,
    `route_version` BIGINT NOT NULL DEFAULT 0,
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    UNIQUE KEY `notification_source_group_rou_source_deployment_id_tenant_i_key` (`source_deployment_id`, `tenant_id`, `legacy_group_id`, `bound_notification_group_id`),
    CONSTRAINT `notification_source_group_routes_engine_check` CHECK (((engine) IN ('legacy', 'encore'))),
    CONSTRAINT `notification_source_group_routes_engine_state_check` CHECK (((((engine) = 'legacy') AND (notification_group_id IS NULL) AND (group_revision = 0)) OR (((engine) = 'encore') AND (notification_group_id IS NOT NULL) AND ((bound_notification_group_id) = (notification_group_id)) AND (group_revision > 0)))),
    CONSTRAINT `notification_source_group_routes_group_revision_check` CHECK ((group_revision >= 0)),
    PRIMARY KEY (`source_deployment_id`, `tenant_id`, `legacy_group_id`),
    CONSTRAINT `notification_source_group_routes_route_version_check` CHECK ((route_version >= 0))
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
-- @@
