    `projected_at` DATETIME(6) NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    UNIQUE KEY `notification_source_group_rou_source_deployment_id_tenant__key1` (`source_deployment_id`, `tenant_id`, `legacy_group_id`, `group_revision`, `notification_group_id`),
    CONSTRAINT `notification_source_group_route_revisions_group_revision_check` CHECK ((group_revision > 0)),
    PRIMARY KEY (`source_deployment_id`, `tenant_id`, `legacy_group_id`, `group_revision`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
