CREATE TABLE IF NOT EXISTS `notification_source_outbox` (
    `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `source_deployment_id` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `tenant_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `source_event_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `source_action_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `legacy_group_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `notification_group_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `group_revision` BIGINT NOT NULL,
    `idempotency_key` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `request_body` LONGBLOB NOT NULL,
    `body_sha256` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `occurred_at` DATETIME(6) NOT NULL,
    `expires_at` DATETIME(6) NOT NULL,
    `state` VARCHAR(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `attempts` INT NOT NULL DEFAULT 0,
    `next_attempt_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `lease_token` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `lease_until` DATETIME(6) NULL,
    `handed_off_at` DATETIME(6) NULL,
    `failure_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `notification_source_outbox_attempts_check` CHECK ((attempts >= 0)),
    CONSTRAINT `notification_source_outbox_check` CHECK ((expires_at > occurred_at)),
    CONSTRAINT `notification_source_outbox_check1` CHECK (((((state) = 'leased') AND (lease_token IS NOT NULL) AND (lease_until IS NOT NULL)) OR (((state) <> 'leased') AND (lease_token IS NULL) AND (lease_until IS NULL)))),
    CONSTRAINT `notification_source_outbox_check2` CHECK (((((state) = 'handed_off') AND (handed_off_at IS NOT NULL)) OR ((state) <> 'handed_off'))),
    CONSTRAINT `notification_source_outbox_group_revision_check` CHECK ((group_revision > 0)),
    PRIMARY KEY (`id`),
    UNIQUE KEY `notification_source_outbox_source_deployment_id_tenant_id_i_key` (`source_deployment_id`, `tenant_id`, `idempotency_key`),
    UNIQUE KEY `notification_source_outbox_source_deployment_id_tenant_id_s_key` (`source_deployment_id`, `tenant_id`, `source_event_id`, `source_action_id`),
    CONSTRAINT `notification_source_outbox_state_check` CHECK (((state) IN ('pending', 'retry_wait', 'leased', 'handed_off', 'blocked', 'failed'))),
    KEY `idx_notification_source_outbox_claim` (`next_attempt_at`, `created_at`),
    KEY `idx_notification_source_outbox_expired_lease` (`lease_until`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
