    `dashboard_id` VARCHAR(99) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `dashboard_name` VARCHAR(99) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
